fn near(cells: &HashMap<(i32, i32), Vec<EntityId>>, x: f32, y: f32, r: f32) -> Vec<EntityId> {
    let mut out = Vec::new();
    for cy in cell_y(y - r)..=cell_y(y + r) {
        for cx in cell_x(x - r)..=cell_x(x + r) {
            out.extend(cells.get(&(cx, cy)).into_iter().flatten().copied());
        }
    }
    out
}

